from pathlib import Path
import json,math,copy,csv
R=Path(__file__).parent;O=R/'output';O.mkdir(exist_ok=True)
P=R/'source/World_Atlas.json';P=P if P.exists() else R.parent/'v3.0.0/World_Atlas.json';W=json.loads(P.read_text());C={c['id']:c for c in W['communities']};C.update({s['id']:dict(name=s['name'],position_km=[s['x'],s['y']],datum_z_m=None) for s in W['sites']})
# Each record develops an existing connection. No new settlement or shortcut is introduced.
notes=[
('Leaving is a civic act','Garden loads, repaired tools and travelers share the road to Latchford. A goodbye at the public entrance can be warm without treating the whole town as an expedition camp.','Departure uses the established east gate and regional approach (1.5,0). The itinerary begins outside the existing interior graph; do not draw a new gate.','An arrival house checks the actual passengers against the sender’s list. The returning goods list and the person count are separate records.','A missing name on a message may be a late passenger, a copy error or deliberate omission. A delayed arrival is a question before it is an accusation.','Open with a shared breakfast, show the exterior transition in a later episode, then cut to a changed sun angle and an overnight halt. Episode one contains none of this.'),
('The high road has a price','Reedbank kitchens buy flour and river households send repaired gear toward the junction. Flood marks on older stone tell the story of collective work, not a prophecy.','The raised causeway and lower river branch are distinct. Closing the lower branch does not automatically close the high route; local observers decide each separately.','Before accepting a lower-branch instruction, compare its observation time with the bank marks. Do not relocate Floodglass Ford onto the main centreline simply to shorten a scene.','A courier pays for a high-route berth, then finds the receipt describes the closed lower branch. The error can be exploited by a broker without making the river a conspiracy.','Keep SITE-01 a separate local branch with no invented regional travel duration. Use the 3.3 habitat sheet if that encounter is staged.'),
('The river keeps two clocks','Millmere needs river deliveries while Reedbank crews need paid docking time. The same current that helps one direction slows the other.','58 km is the inherited route length. Two scheduled days include upstream and docking allowance; the regional 50 km/day rate is a broad planning baseline, not a guarantee against current.','A boat report names direction, water mark, passengers and berth. Reversing the trip requires a new current and docking assessment; two days is not automatically a return timetable.','A sealed cargo receipt arrives before its boat. The arrival clerk must distinguish acceptance of a message from arrival of people.','A waterline, mooring rope and tired crew make elapsed time visible. Do not use a montage to erase a docking wait that changes the plot.'),
('A bed at the junction','The canal service road carries repair pieces too awkward to ship on the day’s boat. Its staffed overnight yard is ordinary infrastructure maintained by people with work of their own.','One staffed overnight yard is established. A three-day road journey still needs a second overnight arrangement; it may be an inspected temporary camp, not a newly named permanent settlement.','The yard registers the chosen next leg rather than assuming all arrivals continue by road. Transfer to WAY-03 is a separate decision, with separate timing.','The last sheltered place belongs to a small party. A larger convoy has to divide its loads and book later departures instead of silently occupying someone else’s space.','Use a reusable camp dressing for the unregistered halt; log weather, water and who stayed awake. Do not add a city to fill a timing gap.'),
('Home behind, stone ahead','Stonewake supplies fittings and skilled hands to the Burrow. Visits carry family expectations as well as cargo; Gorilla can arrive as a brother, apprentice or colleague.','All departures still use the east gate, then the exterior ring road turns northwest. The visual route may curve outside the basin; no western Burrow entrance is created.','Five days is the base loaded-road schedule. Workshop appointments should be set after arrival and rest, not during the last walking block.','A commission expects Gorilla’s strength to replace a second crew. Eris can refuse that assumption without refusing his help.','Use the same packed tools across the five-day sequence. A repaired strap remains repaired; fresh costume changes require laundry or a replacement source.'),
('Where the fields begin to lean','Willowmere sends seeds, teaching materials and orchard produce toward Latchford. Fixed ridge farms supply a landscape of inhabited margins, not empty wilderness.','The forest-margin road is a fixed approach to Willowmere. Moving-crown navigation belongs to the next route and cannot begin wherever an exciting root bridge would look best.','At Willowmere, visitors exchange the road timetable for a guide’s dated canopy briefing. Payment for a guide does not buy the right to overrule a closure.','A crate of viable seed must arrive in shade while a merchant wants it displayed in the sun for customers. The transport problem becomes visible through living cargo.','Let sounds change from wheels and open wind to insects and leaf cover. Carry the same crate dimensions and ventilation marks into the arrival set.'),
('The path is alive, slowly','Guides and bridge crews work between Willowmere and Crownrest. Their songs preserve work sequences; living fibers take seasons to grow.','Six days is the spring guided route; wet-season detour adds two days. Inspection remains necessary even in spring. Roots do not grow a replacement span during a rescue.','A guide signs off the intended crossing state, not the entire forest. A shift in one crown triggers a fresh choice while other communities continue ordinary work.','A reliable old instruction now leads to a gap. It can become dangerous without being forged; the actual forgery plot must still supply independent evidence of deliberate alteration.','Walking Root Crossing uses the 3.3 footprint, spans and rescue shelf. No unmeasured shortcut is added under the canopy. Show waiting and drying gear as part of the journey.'),
('Water travels with the promise','Ossara’s supply relies on handlers, salt grass, wells and animal rest. The caravan carries its dependence visibly: water, feed and cargo occupy the same finite load.','Twelve days includes two water stops and a storm reserve. Do not assign two extra full days to those stops without increasing the total; their durations are not fixed by the old summary.','Before departure, record passengers, animal water, feed, accessible containers and the next confirmed water source. A promised well is not a measured refill.','A packbeast refuses a brilliant-looking shortcut. Checking the harness before the ground lets an ordinary fault and a genuine terrain hazard coexist.','Maintain six legs per sailfin packbeast. Count the same containers at each stop. This production reference does not assign a universal litre ration to all species.'),
('The coast is not the finish','A caravan descends from the dry plateau toward Nacre Quay carrying goods whose ownership may be disputed once they reach water. The coast is a transfer workplace.','230 km at the loaded convoy rate of 18 km/day takes 12.78 movement days. Add the two stated transfer days: 14.78 elapsed days, scheduled as 15 whole day blocks.','Cargo accepted into a quay store is not cargo loaded onto a vessel. Keep warehouse acceptance and departure authority as separate fields.','A valuable sealed chest reaches the quay with two honest owners’ marks from different transfers. The conflict is resolved by reconstructing custody, not by opening every private item.','The old 14-day summary remains in the baseline record. Use the 15-day planning floor for new scenes unless a dated revised itinerary explicitly changes pace or overlap.'),
('An empty berth is useful','The Nacre Quay to Aurel Quay connection serves trade, craft and people visiting relatives. A canceled departure leaves kitchens, workshops and lodging under pressure.','340 km at 100 km/day takes 3.4 movement days. One weather-wait day plus one load/transfer day gives 5.4 elapsed days, scheduled as 6 whole day blocks.','The named sky link is a regional service, not proof that liftstone works everywhere along a straight map line. The selected craft’s support, propulsion, field compatibility and reserve must be established before an airborne sequence.','A captain wins praise for leaving a berth empty, then privately accepts cargo that consumes its weight reserve. Evidence is in the actual load, not the heroic speech.','Do not turn distant liftstone into free-floating ore. The network map is topological; it cannot certify the complete airborne track or the field envelope.'),
('A short flight can take days','Ossara and Aurel Quay trade through finite scheduled craft. Their nearby map positions make waiting feel especially unfair, which gives scenes room for comedy and frustration.','130 km at 100 km/day takes 1.3 movement days. Add two transfer/weather days: 3.3 elapsed days, scheduled as 4 whole day blocks.','A confirmed seat still depends on the inspected craft, load and weather. An unused booking is not a spare aircraft waiting behind the set.','A guest learns every stall in the departure court during a delay, then must leave just as they begin to feel at home. The delay creates a relationship, not only an obstacle.','The earlier three-day summary stays visible as historical input. Future staging uses four planning blocks unless a documented itinerary changes the assumptions.'),
('Warmth has an address','Stonewake crews trade with Hushvale guides and archive workers. A warm refuge is maintained, occupied and finite, not a reward placed at the end of every chase.','Fifteen days covers slower ascent and ridge wayhouses. Winter may close the route entirely. The two-day safe detour around the Cut Span is a separate local itinerary, not automatically included in these fifteen days.','Send departure information before leaving and confirm the next refuge. A late report triggers a bounded search plan; silence alone cannot locate a party.','A familiar voice from the ice offers a shortcut. A visual check and a known warm place are more valuable than a persuasive imitation.','Snow, wet clothing and tool ice persist across cuts. Echo ice and choirwraith mimicry are different mechanisms, neither a resurrection or complete witness.'),
('A road with competing stories','Stonewake’s freight approach reaches Cinder Cuts, where families remember lost work and outsiders often remember only raiders. Both lawful households and coercion exist in the district.','Nine days is the base route. Public and raider-controlled branches are not interchangeable. A paid passage on one branch does not establish safe access to the other.','Record which branch a witness actually saw. A yard document cannot certify the whole inhabited district, and a district name does not make every resident an accomplice.','A stolen load carries a legitimate repair tag from an innocent workshop. Pursuing the tag without asking when the repair occurred threatens the wrong household.','Civilian terraces remain distinct from Ashmouth Freight Yard. Travel shots should include inhabited life before the later crime location, without revealing writer-only villains early.'),
('The freight that went uphill','Cinder Cuts and Kettle Crown share a history of unequal transport decisions. A new contract can provide real work while still asking the poorer terraces to absorb risk.','Three days covers the basalt freight terraces. A gas closure adds one day only for the established limited closure scenario; persistent unsafe conditions mean an indefinite hold.','Local crews check the proposed departure, not an abstract daily quota. A clearance from yesterday does not establish the state of a vent today.','A clean forge yard sends its waste downhill, drawing ashmaws toward another neighborhood. The apparent animal problem points back to a disposal decision.','Ashmaws tolerate hot ground, not liquid lava. Keep safe civic terraces, gas troughs and raider storage geographically distinct.'),
('A descent into someone else’s home','Stonewake’s descent reaches Lumen Tide, an independent community with its own long history. Travelers become guests, not discoverers of an unclaimed world.','The 16 km route changes elevation by 1,920 m from Stonewake z=320 to Lumen Tide z=-1600. Its two-day plan includes pressure and air checks; 16 km is not a straight vertical shaft.','At the descent house, agree equipment, visitor limits, return arrangements and the scope of any chart sharing. No descendant of this route opens below Burrow defenses.','A visitor reads a blank chart margin as an empty coast. A local inhabitant recognizes a protected shore whose omission was intentional.','Regional plan and elevation profile are separate views. Do not draw a uniform shaft gradient: segment-by-segment construction is not defined by the two endpoint elevations.'),
('Three kilometres can fill a day','Lumen Tide crews work Bellwater Narrows as local water, with nesting, craft and rescue responsibilities. A visitor’s three-kilometre distance is not a reason to ignore them.','One day is a local excursion block, not 24 hours of propulsion. Safe tide, quiet movement, transfer and return decisions fill the schedule. No return duration is automatically granted.','Share the usable passage, observation time and warning state without publishing protected nesting coordinates. Keep an author’s full map separate from an in-world visitor chart.','A depth correction helps a rescue without proving the visitor needs ownership of the whole chart. Namu can accept useful evidence while maintaining a boundary.','Use the 3.3 boat approach, dock boarding link, stairs and upper refuge. Water and the high arch occupy different elevations. Light does not repel bell-eels.')]
corrections={'WAY-09':dict(moving=230/18,layover=2,days=15),'WAY-10':dict(moving=340/100,layover=2,days=6),'WAY-11':dict(moving=130/100,layover=2,days=4)}
cards=[]
for r,n in zip(W['routes'],notes):
 c=dict(id=r['id'],baseline=copy.deepcopy(r),origin_name=C[r['a']]['name'],destination_name=C[r['b']]['name'],title=n[0],daily_life=n[1],timing=n[2],handoff=n[3],story_option=n[4],production=n[5],schedule_days=corrections.get(r['id'],{}).get('days',r['days']),schedule_status='Explicit planning erratum' if r['id'] in corrections else 'Inherited base schedule',direction='Listed a-to-b planning reference; reverse passage requires a fresh itinerary.',geometry='Regional endpoints and route length inherited; connecting line is not a surveyed track.')
 if r['id'] in corrections:c['arithmetic']=corrections[r['id']]
 cards.append(c)
examples=[dict(id='JRN-01',name='A first canopy journey',route_ids=['WAY-01','WAY-06','WAY-07'],reason='Burrow to Latchford to Willowmere to Crownrest',extra_days=0,condition='Spring baseline; guide and next departure available.'),dict(id='JRN-02',name='The same journey after rain',route_ids=['WAY-01','WAY-06','WAY-07'],reason='Same geography; two additional days on the wet-season canopy detour.',extra_days=2,condition='Detour open and inspected. A closure is not a two-day delay by default.'),dict(id='JRN-03',name='Cargo from home to the coast',route_ids=['WAY-01','WAY-04','WAY-08','WAY-09'],reason='Burrow - Latchford - Millmere - Ossara - Nacre Quay',extra_days=0,condition='Uses the corrected 15-day coast leg. No extra inter-leg booking wait included.'),dict(id='JRN-04',name='A visit below the surface',route_ids=['WAY-05','WAY-15','WAY-16'],reason='Burrow - Stonewake - Lumen Tide - Bellwater Narrows',extra_days=0,condition='Seven days to Lumen Tide, then one excursion block; no hidden Burrow descent.'),dict(id='JRN-05',name='The sky route through Ossara',route_ids=['WAY-01','WAY-04','WAY-08','WAY-11'],reason='Burrow - Latchford - Millmere - Ossara - Aurel Quay',extra_days=0,condition='Uses corrected four-day scheduled sky leg; conditional on compatible craft and corridor.'),dict(id='JRN-06',name='Freight to the forge terraces',route_ids=['WAY-05','WAY-13','WAY-14'],reason='Burrow - Stonewake - Cinder Cuts - Kettle Crown',extra_days=1,condition='Includes the specific one-day gas closure allowance, not indefinite clearance.')]
by={r['id']:r for r in cards}
for ex in examples:
 elapsed=0;segments=[];prev=None
 for rid in ex['route_ids']:
  r=by[rid];b=r['baseline'];assert prev in [None,b['a']];prev=b['b'];segments.append(dict(route=rid,start_elapsed_day=elapsed,end_elapsed_day=elapsed+r['schedule_days']));elapsed+=r['schedule_days']
 ex['segments']=segments;ex['base_leg_sum_days']=elapsed;ex['elapsed_day_blocks']=elapsed+ex['extra_days'];ex['status']='Planning example only; no episode-ledger adoption or calendar date.'
rules=[('Distance is not elapsed time','Keep movement, transfer, weather hold and recovery distinct. Add full stated layovers before rounding to whole planning day blocks. Do not add them again if the base schedule already includes them.'),('Record direction','The same road may be traversable both ways, but the atlas lists one planning direction. Current, ascent, loading and departures can make the reverse schedule different.'),('A message is not an arrival','A relay acknowledgment means a message reached a relay. Only a grounded arrival observation can establish where a traveler was. Preserve the sender, observation time and meaning of each field.'),('One gate remains one gate','The Burrow’s east public gate serves northwest departures through the exterior ring road. Interior access and defensive closure remain the 2.1 graph; neither sky nor deep routes create a bypass.'),('Ordinary life travels too','Give each departure one domestic intention: returning a pan, visiting a sibling, delivering seedlings, finishing a song. Travel scenes can delight and surprise without introducing a new threat each day.'),('Closure has no promised ending','A stated detour allowance applies only while that detour is open. Unsafe tide, air, weather or structure can extend a delay indefinitely; the plot must carry food, accommodation and changed commitments.'),('No invented season dates','The world uses a 360-day year, twelve 30-day months and six-day weeks. Local ecological cues vary; that does not erase the established civic calendar. Relative travel examples below do not date an episode.'),('Useful technology has a boundary','Liftstone is field-bound; echo ice repeats fragments; mirage glass preserves partial light; canopy shaping takes seasons; resonant spans can fail in chains; ordinary relays need power and access. No system grants universal travel, proof or control.')]
D=dict(edition='3.4.0',title='Journeys & Waycraft',date='2026-10-21',base_commit='4f3633b4a6e021e9c31053a970d4263be5a2116d',scope='Sixteen existing routes, exact regional anchors, six timing examples, six bounded technologies and one complete proposed story.',route_cards=cards,planning_examples=examples,rules=[dict(title=a,text=b) for a,b in rules],waycraft=W['waycraft'],communities=W['communities'],site_endpoint=dict(id='SITE-08',name=C['SITE-08']['name'],position_km=C['SITE-08']['position_km']),timing_errata=[dict(route_id=k,old_days=by[k]['baseline']['days'],moving_days=v['moving'],full_layover_days=v['layover'],exact_elapsed_days=v['moving']+v['layover'],planning_day_blocks=v['days'],reason='Full stated layovers added to movement at the inherited regional rate; round upward once.') for k,v in corrections.items()],authority='Additive writer reference. Only the three explicitly identified planning durations supersede old route-day summaries. No geography, elapsed story event, character history or dated episode changes.',pilot_exterior_scenes=0)
(O/'Journeys_Bible.json').write_text(json.dumps(D,indent=2));(O/'cards').mkdir(exist_ok=True)
for c in cards:(O/'cards'/f"{c['id']}.json").write_text(json.dumps(c,indent=2))
with (O/'Route_Register.csv').open('w') as f:
 wr=csv.writer(f);wr.writerow(['id','origin','destination','mode','length_km','old_summary_days','planning_days','status'])
 for c in cards:wr.writerow([c['id'],c['origin_name'],c['destination_name'],c['baseline']['mode'],c['baseline']['length_km'],c['baseline']['days'],c['schedule_days'],c['schedule_status']])
print('16 route dossiers, 6 planning examples, 3 explicit timing errata.')
